  $src$[{"label":"European AI Act — práva občanov","url":"https://digital-strategy.ec.europa.eu/en/policies/regulatory-framework-ai"},{"label":"GDPR — ochrana osobných údajov EÚ","url":"https://gdpr.eu/"},{"label":"OpenAI — nastavenia súkromia","url":"https://openai.com/security-and-privacy"},{"label":"ENISA — kybernetická bezpečnosť a AI","url":"https://www.enisa.europa.eu/"}]$src$::jsonb,
